          "duration": { "type": "fixed", "seconds": 180 },
          "startTrigger": { "type": "afterStep", "stepId": "simmer-lentils" }
        },
        {
          "stepId": "warm-bread",
          "name": "Warm bread in toaster oven",
          "task": "toaster-oven",
          "duration": { "type": "fixed", "seconds": 480 },
          "startTrigger": { "type": "afterStep", "stepId": "cut-bread" }
        },
        {
          "stepId": "wrap-bread",
          "name": "Wrap warm bread in a cloth",
          "task": "prep",
          "duration": { "type": "fixed", "seconds": 60 },
          "startTrigger": { "type": "afterStep", "stepId": "warm-bread" }
        }
      ]
    },
    {
      "trackId": "table",
      "name": "Table",
      "steps": [
        {
          "stepId": "lay-table",
          "name": "Lay four places",
          "task": "prep",
          "duration": { "type": "fixed", "seconds": 300 },
          "startTrigger": { "type": "afterStep", "stepId": "wrap-bread" }
        },
        {
          "stepId": "serve",
          "name": "Carry pot and bowl through",
          "task": "prep",
          "duration": { "type": "fixed", "seconds": 180 },
          "startTrigger": { "type": "compound", "logic": "all", "triggers": [
            { "type": "afterStep", "stepId": "season-soup" },
            { "type": "afterStep", "stepId": "dress-salad" },
            { "type": "afterStep", "stepId": "wrap-bread" }
          ] }
        }
      ]
    }
  ],
  "resourceConstraints": [
    { "task": "prep", "maxConcurrent": 1 },
    { "task": "stove", "maxConcurrent": 2 },
    { "task": "toaster-oven", "maxConcurrent": 1 }
  ],
  "metadata": { "serves": "4" }
}
